CREATE TABLE cash_tx (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    date      TEXT NOT NULL,
    owner_id  INTEGER NOT NULL REFERENCES owners(id),
    type      TEXT NOT NULL,
    amount    REAL NOT NULL,
    symbol    TEXT,
    group_id  TEXT,
    note      TEXT
);
